from pathlib import Path
import json
ROOT=Path(__file__).parent
R=r'''(()=>{const C=__CFG__,old=document.getElementById('abx-util');if(old)old.remove();let d=document.createElement('div');d.id='abx-util';d.innerHTML=`<style>#abx-util{position:fixed;z-index:2147483647;inset:0;background:#090d18ee;color:#e5e7eb;font:16px system-ui;display:grid;place-items:center}#abx-util .u{width:min(92vw,680px);max-height:86vh;overflow:auto;background:#111827;border:2px solid #22d3ee;border-radius:18px;padding:24px;box-shadow:0 20px 70px #000}#abx-util h1{color:#67e8f9;margin-top:0}#abx-util textarea,#abx-util input,#abx-util select{box-sizing:border-box;width:100%;padding:11px;margin:7px 0;background:#0b1220;color:#fff;border:1px solid #475569;border-radius:8px}#abx-util button{padding:10px 15px;margin:5px 5px 5px 0;border:0;border-radius:8px;background:#22d3ee;color:#06202a;font-weight:700;cursor:pointer}.close{float:right;background:#334155!important;color:#fff!important}.out{white-space:pre-wrap;background:#0b1220;padding:12px;border-radius:8px;min-height:30px}</style><div class=u><button class=close>×</button><h1>${C.title}</h1><p>${C.desc}</p><div id=body></div></div>`;document.body.appendChild(d);d.querySelector('.close').onclick=()=>d.remove();let b=d.querySelector('#body'),out=x=>b.querySelector('.out').textContent=x,esc=x=>x.replace(/[&<>]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[m]));if(C.mode==='notes')b.innerHTML='<textarea rows=15 placeholder="メモを書く..."></textarea><button id=save>保存</button><button id=clear>消去</button><div class=out></div>',b.querySelector('textarea').value=localStorage.abxnotes||'',b.querySelector('#save').onclick=()=>{localStorage.abxnotes=b.querySelector('textarea').value;out('保存しました')},b.querySelector('#clear').onclick=()=>{b.querySelector('textarea').value='';localStorage.removeItem('abxnotes');out('消去しました')};if(C.mode==='timer')b.innerHTML='<input id=n type=number value=5 min=1><button id=go>開始</button><div class=out></div>',b.querySelector('#go').onclick=()=>{let n=+b.querySelector('#n').value;out(n+'秒');let t=setInterval(()=>{out((--n)+'秒');if(n<=0){clearInterval(t);out('時間です！')}},1000)};if(C.mode==='counter')b.innerHTML='<button id=minus>−</button><button id=plus>＋</button><button id=reset>リセット</button><div class=out>0</div>',b.querySelector('#plus').onclick=()=>out(String(+(b.querySelector('.out').textContent)+1)),b.querySelector('#minus').onclick=()=>out(String(+(b.querySelector('.out').textContent)-1)),b.querySelector('#reset').onclick=()=>out('0');if(C.mode==='color')b.innerHTML='<input id=c type=color value="#22d3ee"><div class=out></div>',b.querySelector('#c').oninput=e=>{out(e.target.value);navigator.clipboard?.writeText(e.target.value)};if(C.mode==='base64')b.innerHTML='<textarea id=i rows=7 placeholder="文字列"></textarea><button id=e>エンコード</button><button id=d>デコード</button><div class=out></div>',b.querySelector('#e').onclick=()=>out(b.querySelector('#i').value?btoa(unescape(encodeURIComponent(b.querySelector('#i').value))):''),b.querySelector('#d').onclick=()=>{try{out(decodeURIComponent(escape(atob(b.querySelector('#i').value))))}catch(e){out('デコードできません')}};if(C.mode==='url')b.innerHTML='<textarea id=i rows=5 placeholder="URLや文章"></textarea><button id=e>URLエンコード</button><button id=d>デコード</button><div class=out></div>',b.querySelector('#e').onclick=()=>out(encodeURIComponent(b.querySelector('#i').value)),b.querySelector('#d').onclick=()=>{try{out(decodeURIComponent(b.querySelector('#i').value))}catch(e){out('形式が不正です')}};if(C.mode==='json')b.innerHTML='<textarea id=i rows=10 placeholder="JSON"></textarea><button id=f>整形</button><button id=m>圧縮</button><div class=out></div>',b.querySelector('#f').onclick=()=>{try{out(JSON.stringify(JSON.parse(b.querySelector('#i').value),null,2))}catch(e){out('JSONが不正です')}},b.querySelector('#m').onclick=()=>{try{out(JSON.stringify(JSON.parse(b.querySelector('#i').value)))}catch(e){out('JSONが不正です')}};if(C.mode==='timestamp')b.innerHTML='<button id=now>現在時刻</button><div class=out></div>',b.querySelector('#now').onclick=()=>out(new Date().toString()+'\n'+Date.now());if(C.mode==='random')b.innerHTML='<input id=n type=number value=10><button id=go>生成</button><div class=out></div>',b.querySelector('#go').onclick=()=>out([...Array(+b.querySelector('#n').value||10)].map(()=>Math.random().toString(36).slice(2,8)).join('\n'));if(C.mode==='calc')b.innerHTML='<input id=i placeholder="例: (12+3)*4"><button id=go>計算</button><div class=out></div>',b.querySelector('#go').onclick=()=>{try{let x=b.querySelector('#i').value;if(!/^[0-9+*/().% -]+$/.test(x))throw 0;out(String(Function('return '+x)()))}catch(e){out('計算できません')}};if(C.mode==='count')b.innerHTML='<textarea id=i rows=10 placeholder="文章"></textarea><button id=go>数える</button><div class=out></div>',b.querySelector('#go').onclick=()=>{let x=b.querySelector('#i').value;out(`文字数: ${x.length}\n行数: ${x?x.split(/\n/).length:0}\n単語らしき数: ${(x.match(/\S+/g)||[]).length}`)};if(C.mode==='focus')b.innerHTML='<input id=m value=25 min=1 type=number><button id=go>集中開始</button><div class=out></div>',b.querySelector('#go').onclick=()=>{let n=+b.querySelector('#m').value*60;let t=setInterval(()=>{out(Math.floor(n/60)+':'+String(n%60).padStart(2,'0'));if(--n<0){clearInterval(t);out('休憩しましょう')}} ,1000)};if(C.mode==='palette')b.innerHTML='<button id=go>パレット生成</button><div class=out></div>',b.querySelector('#go').onclick=()=>out([...Array(5)].map(()=>`#${Math.floor(Math.random()*16777215).toString(16).padStart(6,'0')}`).join('\n'));if(C.mode==='query')b.innerHTML='<input id=i placeholder="検索語"><button id=go>ページ内検索</button><div class=out></div>',b.querySelector('#go').onclick=()=>{let q=b.querySelector('#i').value;out(q?[...document.body.innerText.matchAll(new RegExp(q.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),'gi'))].length+'件見つかりました':'検索語を入力してください')};if(C.mode==='scroll')b.innerHTML='<button id=top>上へ</button><button id=bottom>下へ</button><div class=out>ページ移動</div>',b.querySelector('#top').onclick=()=>scrollTo({top:0,behavior:'smooth'}),b.querySelector('#bottom').onclick=()=>scrollTo({top:document.body.scrollHeight,behavior:'smooth'});if(C.mode==='links')b.innerHTML='<button id=go>リンク一覧を表示</button><div class=out></div>',b.querySelector('#go').onclick=()=>out([...document.links].map((a,i)=>`${i+1}. ${a.textContent.trim()||'(無題)'}\n${a.href}`).join('\n'));if(C.mode==='fullscreen')b.innerHTML='<button id=go>フルスクリーン</button><div class=out>Escで解除</div>',b.querySelector('#go').onclick=()=>document.documentElement.requestFullscreen?.();if(C.mode==='print')b.innerHTML='<button id=go>印刷ダイアログ</button><div class=out>印刷設定を開きます</div>',b.querySelector('#go').onclick=()=>print();})()'''

def line(cfg): return 'javascript:'+R.replace('__CFG__',json.dumps(cfg,ensure_ascii=False,separators=(',',':')))
items=[('クイックメモ','notes','ブラウザに自動保存するメモ'),('カウント台','counter','数を増減して数える'),('秒数タイマー','timer','短いタイマー'),('カラーピッカー','color','色コードをコピー'),('Base64変換','base64','Base64の相互変換'),('URLエンコーダー','url','URL文字列を変換'),('JSON整形','json','JSONを整形・圧縮'),('現在時刻','timestamp','日時とUNIX時刻'),('ランダム文字列','random','安全な短い候補を生成'),('計算機','calc','四則演算を計算'),('文章カウンター','count','文字・行・単語を計数'),('集中タイマー','focus','ポモドーロ風タイマー'),('配色ジェネレーター','palette','5色をランダム生成'),('ページ内検索','query','現在ページの語数を検索'),('ページ先頭末尾','scroll','ページ移動ボタン'),('リンク一覧','links','ページ内リンクを書き出す'),('フルスクリーン','fullscreen','ページを全画面表示'),('印刷ヘルパー','print','印刷ダイアログを開く'),('ランダムID工房','random','複数のIDを生成'),('ミニタイマー','timer','作業用の秒数タイマー')]
xs=[]
for i,(title,mode,desc) in enumerate(items,1):
 c={'no':i,'title':f'{i:02d} {title}','mode':mode,'desc':desc}
 xs.append({**c,'code':line(c)})
(ROOT/'utilities.json').write_text(json.dumps(xs,ensure_ascii=False,indent=2),encoding='utf-8')
with (ROOT/'utilities.js').open('w',encoding='utf-8') as f:
 f.write('// Abloxmusic utility bookmarklets: each javascript: line is standalone.\n')
 for x in xs:f.write(f"// {x['no']:02d} {x['title']}\n{x['code']}\n")
html='''<!doctype html><meta charset="utf-8"><title>Abloxmusic便利アプリ20</title><style>body{background:#080b16;color:#eef2ff;font:16px system-ui;padding:30px}main{max-width:900px;margin:auto}h1{color:#67e8f9}.card{display:grid;grid-template-columns:50px 1fr auto;gap:12px;align-items:center;background:#111827;border:1px solid #263449;border-radius:12px;padding:12px;margin:8px 0}.n{color:#67e8f9;font:700 20px monospace}.m{color:#94a3b8;font-size:13px}button{background:#164e63;color:#e0f2fe;border:1px solid #22d3ee;border-radius:8px;padding:9px;cursor:pointer}</style><main><h1>便利アプリ20</h1><p>コピーした1行をブックマークURLに貼り付けて使えます。外部通信なし。</p><section id=l></section></main><script>const U=__DATA__,l=document.querySelector('#l');l.innerHTML=U.map(x=>`<article class=card><div class=n>${String(x.no).padStart(2,'0')}</div><div><b>${x.title}</b><div class=m>${x.mode} / ${x.desc}</div></div><button data-n=${x.no}>1行をコピー</button></article>`).join('');document.querySelectorAll('button').forEach(b=>b.onclick=()=>{navigator.clipboard.writeText(U.find(x=>x.no==b.dataset.n).code);b.textContent='コピー済み'})</script>'''
(ROOT/'utilities.html').write_text(html.replace('__DATA__',json.dumps(xs,ensure_ascii=False,separators=(',',':'))),encoding='utf-8')
print('generated',len(xs),'utilities')
